import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {canonicalLf,sha256} from '../testing/maintenance-db-contract.mjs';

const indexFile='scripts/audit/on-prices225-source-pins.json';
const indexText=canonicalLf(readFileSync(new URL('./on-prices225-source-pins.json',import.meta.url),'utf8'));
const pins=JSON.parse(indexText);
assert.equal(pins.format,1);
assert.equal(pins.baseline,'78f47ccdd7698cf95ee69dc1ae05ba2fd53da301');
/** @type {Record<string,{before:string|null,after:string,beforeText:string|null}>} */
export const onPrices225Pins=pins.entries;
for(const [file,pin] of Object.entries(onPrices225Pins)){
 assert.ok(!file.includes('..')&&!file.startsWith('/')&&!file.startsWith('.env'));
 assert.match(pin.after,/^[a-f0-9]{64}$/u);
 assert.equal(pin.beforeText===null?null:sha256(pin.beforeText),pin.before,'ON_PRICES225_HISTORY_PIN_CORRUPT:'+file);
}
export function sourceBeforeOnPrices225(file,text){
 if(text===null)return null;
 const raw=canonicalLf(text);
 if(file===indexFile&&raw===indexText)return null;
 const pin=onPrices225Pins[file];
 return pin&&sha256(raw)===pin.after?pin.beforeText:text;
}
const current=file=>canonicalLf(readFileSync(new URL('../../'+file,import.meta.url),'utf8'));
export function restoreOnPrices225Hashes(rows){
 return rows.flatMap(row=>{
  const pin=onPrices225Pins[row.file];
  if(!pin||row.sha256!==pin.after)return[row];
  assert.equal(sha256(current(row.file)),pin.after,'ON_PRICES225_HISTORY_SOURCE_CHANGED:'+row.file);
  return pin.before===null?[]:[{...row,sha256:pin.before}];
 });
}
/** @param {string[]} files */
export function pathsBeforeOnPrices225(files){
 return files.filter(file=>{
  if(file===indexFile)return current(file)!==indexText;
  const pin=onPrices225Pins[file];
  return !pin||pin.before!==null||sha256(current(file))!==pin.after;
 });
}

scripts/testing/legacy224-owner-tools.mj.beforeText:
// Test-only checkout for retired owner command admission. No linked project.
import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {mkdtemp,lstat,readFile,realpath,rm,symlink,unlink} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {promisify} from 'node:util';

const exec=promisify(execFile);
const baseline='78f47ccdd7698cf95ee69dc1ae05ba2fd53da301';
const prefix='nawasrah-legacy224-owner-tools-';

export async function withLegacy224OwnerTools(root,run){
 const temporary=await realpath(tmpdir());
 const checkout=await mkdtemp(path.join(temporary,prefix));
 const dependencies=path.join(checkout,'node_modules');
 let linked=false;
 try{
  await exec('git',['merge-base','--is-ancestor',baseline,'HEAD'],{cwd:root,windowsHide:true});
  await exec('git',['clone','--shared','--no-checkout',root,checkout],{windowsHide:true});
  const runGit=args=>exec('git',args,{cwd:checkout,windowsHide:true});
  await runGit(['config','--local','core.autocrlf','false']);
  await runGit(['config','--local','core.eol','lf']);
  await runGit(['checkout','--detach',baseline]);
  assert.equal((await runGit(['rev-parse','HEAD'])).stdout.trim(),baseline);
  assert.equal((await runGit(['status','--porcelain'])).stdout,'');
  for(const adapter of ['frankfurt-owner-upgrade220','frankfurt-owner-reset220','frankfurt-owner-reset224']){
   const file='scripts/operations/'+adapter+'.mjs';
   assert.deepEqual(await readFile(path.join(root,file)),await readFile(path.join(checkout,file)),'LEGACY224_OWNER_ADAPTER_CHANGED:'+adapter);
  }
  await symlink(path.join(root,'node_modules'),dependencies,process.platform==='win32'?'junction':'dir');
  linked=true;
  return await run(checkout);
 }finally{
  assert.equal(path.dirname(await realpath(checkout)),temporary);
  assert.ok(path.basename(checkout).startsWith(prefix));
  assert.ok(!(await lstat(checkout)).isSymbolicLink());
  if(linked){assert.ok((await lstat(dependencies)).isSymbolicLink());await unlink(dependencies);}
  await rm(checkout,{recursive:true,force:true});
 }
}

